    public function list(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("List Theme version");
        $span = $this->startSpan("List Theme version");
        try {
            $params = $request->getQueryParams();
            $filter = new ThemeVersionFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                theme: isset($params['theme']) ? new ThemeRef($params['theme']) : null,
                themes: isset($params['themes']) ? explode(",", $params['themes']) : null,
            );
            $cursor = new ThemeVersionCursor(
                limit: (int)($params['limit'] ?? 100),
                sinceUid: $params['since-uid'] ?? null,
            );
            $result = $this->listUsecase->list($filter, $cursor);
            $value = ['items' => array_map(fn (ThemeVersionAttributes $item): ThemeVersionApiDTO => $this->mapThemeVersion($request, $item), $result->values())];
            $nextLink = $this->nextLink($result->cursor(), $params);
            if (null !== $nextLink) {
