    private function nextLink(?ThemeVersionCursor $value, array $params): ?string
    {
        $this->logDebug("Check generic allow for Theme version");
        $span = $this->startSpan("Generic allow for Theme version");
        try {
            if (!$value) {
                return null;
            }
            $link = [];
            if (isset($params['limit'])) {
                $link['limit'] = 'limit=' . $params['limit'];
            }
            $sinceUid = $value->sinceUid();
            if (null !== $sinceUid) {
                $link['since-uid'] = 'since-uid=' . urlencode($sinceUid);
            }
            return implode('&', $link);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapThemeVersion(ServerRequestInterface $request, ThemeVersionAttributes $value): ThemeVersionApiDTO
