        $span = $this->startSpan("Map entity to output dto for Theme version");
        try {
            $theme = $value->getTheme();
            $dto = new ThemeVersionApiDTO();
            $dto->uid = $value->getUid();
            $dto->theme = $theme ? ['$ref' => $theme->uid()] : null;
            $dto->channel = $value->getChannel();
            $dto->locale = $value->getLocale();
            $dto->contentHtml = $value->getContentHtml();
            $dto->contentText = $value->getContentText();
            $dto->version = $value->getVersion();
